#!/usr/bin/env python3
"""Embed the optional dashboard in the single-file CLI distribution."""

import base64
import json
from pathlib import Path
import sys
import tempfile


ROOT = Path(__file__).resolve().parent.parent
OUTPUT = ROOT / "src" / "83-dashboard-bundle.sh"


def bundle():
    assets = {
        "/": (ROOT / "dashboard" / "index.html").read_text(encoding="utf-8"),
    }
    for name in ("app.js", "styles.css", "experience.js", "experience.css"):
        assets["/" + name] = (ROOT / "dashboard" / name).read_text(encoding="utf-8")
    # Plain base64 keeps generated bytes identical across Python/zlib versions.
    # Assets are small enough that compression is not worth a drifting build.
    encoded = base64.b64encode(json.dumps(
        assets, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")).decode("ascii")
    literals = "\n".join(
        "    " + repr(encoded[i:i + 100]) for i in range(0, len(encoded), 100)
    )
    server = (ROOT / "dashboard" / "server.py").read_text(encoding="utf-8")
    # Avoid hidden dependence on generated files or the current directory.
    compile(server, "dashboard/server.py", "exec")
    return (
        "# Generated by scripts/bundle-dashboard.py. Edit dashboard/ instead.\n"
        "# The server and frontend are in memory; no extraction directory is used.\n"
        "dashboard_runtime() {\n"
        '  local dashboard_python="$1"\n'
        "  shift\n"
        '  "$dashboard_python" -I - "$SELF_PATH" "$@" <<\'AIDENTITY_DASHBOARD_PY\'\n'
        "import base64, json\n"
        "ASSETS = json.loads(base64.b64decode(\n"
        + literals
        + "\n))\n"
        + server.rstrip()
        + "\nAIDENTITY_DASHBOARD_PY\n"
        "}\n"
    )


def main():
    if sys.argv[1:] not in ([], ["--check"]):
        raise SystemExit("Usage: scripts/bundle-dashboard.py [--check]")
    content = bundle()
    if sys.argv[1:] == ["--check"]:
        if not OUTPUT.exists() or OUTPUT.read_text(encoding="utf-8") != content:
            raise SystemExit("The dashboard bundle is stale. Run: make build")
        return
    with tempfile.NamedTemporaryFile(
        mode="w", encoding="utf-8", dir=OUTPUT.parent, delete=False
    ) as staged:
        staged.write(content)
        staged_path = Path(staged.name)
    try:
        staged_path.chmod(0o644)
        staged_path.replace(OUTPUT)
    finally:
        staged_path.unlink(missing_ok=True)
    print("Bundled dashboard/server.py and five frontend assets.")


if __name__ == "__main__":
    main()
